import{_ as t,o as n,c as r,ah as a}from"./chunks/framework.C-FRNfAJ.js";const u=JSON.parse('{"title":"Enrolments and agreements","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/coordinateur/inscriptions.md","filePath":"src/en/guide/coordinateur/inscriptions.md"}'),o={name:"en/guide/coordinateur/inscriptions.md"};function s(i,e,h,g,d,l){return n(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="enrolments-and-agreements" tabindex="-1">Enrolments and agreements <a class="header-anchor" href="#enrolments-and-agreements" aria-label="Permalink to &quot;Enrolments and agreements&quot;">​</a></h1><p><strong>Journeys → Enrolments</strong> lists the admitted learners, with their program, cohort, format, status and consents. Filter by status (To sign, Active, Suspended, Dropped, Completed), by program, or on <strong>Without cohort</strong>.</p><h2 id="placing-a-learner" tabindex="-1">Placing a learner <a class="header-anchor" href="#placing-a-learner" aria-label="Permalink to &quot;Placing a learner&quot;">​</a></h2><p>An enrolment <strong>without cohort</strong> (the advisor chose none at admission, or the cohort was cancelled) carries the &quot;To place&quot; marker. <strong>Place</strong> opens the list of cohorts that can take them: not yet started, with a seat and a price for their format. The learner is told by e-mail. <strong>Move</strong> does the same for an already placed learner, as long as they have not signed.</p><p>Every non-dropped enrolment <strong>takes a seat</strong>. Headcount and profitability zone only count <strong>signed</strong> enrolments.</p><h2 id="funding" tabindex="-1">Funding <a class="header-anchor" href="#funding" aria-label="Permalink to &quot;Funding&quot;">​</a></h2><p>Before signing, <strong>Funding</strong> lets you designate a <strong>funder</strong> (an organization account with the Funder role) and their share, from 1 to 100%. &quot;None&quot; leaves the learner paying everything. The split appears in the agreement. See <a href="./../entreprises/financeur.html">Funding learners</a>.</p><h2 id="the-business-referrer" tabindex="-1">The business referrer <a class="header-anchor" href="#the-business-referrer" aria-label="Permalink to &quot;The business referrer&quot;">​</a></h2><p><strong>Business referrer</strong> links the enrolment to the account that brought it, if any. The code (<code>AP-XXXXXX</code>) is normally entered by the candidate; you can correct it <strong>until the first payment</strong>. The referrer earns 5% of each payment (see <a href="./remunerations.html">Remunerations and commissions</a>).</p><h2 id="the-agreement-text" tabindex="-1">The agreement text <a class="header-anchor" href="#the-agreement-text" aria-label="Permalink to &quot;The agreement text&quot;">​</a></h2><p>From <strong>Enrolments</strong>, the <strong>agreement text</strong> (the general terms) is published in <strong>immutable versions</strong>: once published, a version can no longer be edited. A new version applies to <strong>following</strong> signatures; each signed agreement keeps the one it signed. <strong>Without a published text, no agreement can be signed.</strong></p><p>Kura adds to this text the specific terms (parties, program, cohort, format, price excluding tax, 30/40/30 schedule).</p><h2 id="counter-signature" tabindex="-1">Counter-signature <a class="header-anchor" href="#counter-signature" aria-label="Permalink to &quot;Counter-signature&quot;">​</a></h2><p>When the learner has signed, edPage group must counter-sign. The Administrator sets whether counter-signature is <strong>automatic</strong> (in the representative&#39;s name, the default) or <strong>manual</strong>. In manual mode, agreements to counter-sign appear in enrolments, filterable by <strong>To counter-sign</strong>, with the <strong>Counter-sign</strong> button.</p><p>On counter-signature: the agreement receives its reference <code>CONV-NB-YYYY-XXX</code> and its sealed PDF, sent to the learner; the enrolment becomes <strong>active</strong>; the format, cohort and price are fixed; the first invoice is issued.</p><h3 id="the-tripartite-agreement" tabindex="-1">The tripartite agreement <a class="header-anchor" href="#the-tripartite-agreement" aria-label="Permalink to &quot;The tripartite agreement&quot;">​</a></h3><p>When an agreement with a funder is counter-signed, Kura prepares the <strong>tripartite agreement</strong>. The funder signs it; in manual mode, you counter-sign with <strong>Counter-sign the tripartite</strong>. It blocks neither the enrolment nor billing.</p><h2 id="the-internship-agreement" tabindex="-1">The internship agreement <a class="header-anchor" href="#the-internship-agreement" aria-label="Permalink to &quot;The internship agreement&quot;">​</a></h2><p>For a learner whose training includes an internship, <strong>Enter the internship</strong> (then <strong>Edit the internship</strong>) asks for:</p><ul><li>the <strong>host company</strong> and its <strong>signing contact</strong> (name and e-mail);</li><li>the <strong>Coach-Tutor</strong> supervising the internship, chosen among the cohort&#39;s;</li><li>the start and end <strong>dates</strong>, and the <strong>mission</strong>.</li></ul><p><strong>Send the internship agreement to sign</strong> starts the signatures: the learner (or their legal guardian if a minor) and the company, by link and code. As long as <strong>no signature</strong> has been given, you can edit the internship; <strong>any edit withdraws the agreement sent</strong> and it must be sent again. When both parties have signed, edPage counter-signs (<strong>Counter-sign the internship</strong> in manual mode).</p><p>The company name is reused in the jury&#39;s evaluation of the internship. An internship without an agreement remains possible: the jury then enters the company by hand.</p><h2 id="changing-cohort-force-majeure" tabindex="-1">Changing cohort (force majeure) <a class="header-anchor" href="#changing-cohort-force-majeure" aria-label="Permalink to &quot;Changing cohort (force majeure)&quot;">​</a></h2><p><strong>Change cohort (force majeure)</strong> moves a learner on proof: enter the <strong>reason and proof</strong> (for example &quot;medical certificate of 12 March&quot;). They move to the next session of the same program, their payments are kept (what is still owed on the invoices already issued is cancelled by a credit note, then billed again under the new agreement, deducting what is already paid) and no partial attestation is issued.</p><p>After signing, any change of cohort <strong>replaces the agreement</strong>: the old one is kept, the enrolment goes back to pending signature, and a new agreement, at the same price and format, is to be signed. The learner is notified.</p><h2 id="recording-a-drop-out" tabindex="-1">Recording a drop-out <a class="header-anchor" href="#recording-a-drop-out" aria-label="Permalink to &quot;Recording a drop-out&quot;">​</a></h2><p><strong>Record a drop-out</strong> ends the enrolment. Choose the reason:</p><ul><li><strong>Voluntary drop-out</strong>;</li><li><strong>Unenrolled for non-payment</strong> (after D+30, with no settlement).</li></ul><p>A note is optional. The seat is freed and the learner leaves the headcount. No credit note is issued: instalments not yet invoiced will no longer be, invoices already issued remain due. If at least one block is validated, you can issue a <strong>partial attestation</strong> (see <a href="./resultats.html#the-partial-attestation">Results and certification</a>).</p><h2 id="consents" tabindex="-1">Consents <a class="header-anchor" href="#consents" aria-label="Permalink to &quot;Consents&quot;">​</a></h2><p>The <strong>Consents</strong> column shows each learner&#39;s answer: &quot;Reuse&quot; and &quot;Image&quot;, or &quot;Awaited&quot;. Both are required before signing. A <strong>minor</strong> learner is flagged: their consents and signature are those of their legal guardian.</p>',31)])])}const m=t(o,[["render",s]]);export{u as __pageData,m as default};
